      '重复孵到同一只 → 转成**兽魂**；兽魂用来升阶，每升一阶在基础加成上再 +15%，满级 Lv.10。',
      '**五行克制**：每个残域有自己的属性，伴生体也有属性。金克木、木克土、土克水、水克火、火克金——带对了克制的伴生体进本，全队伤害 +15%，带反了 -8%。',
      '所以打不过某个世界时，先看一眼它的属性，换一只克它的伴生体再去，比硬堆战力便宜得多。',
